package app.thumbfree.core

import java.io.File
import kotlin.test.Test
import kotlin.test.fail

/**
 * The same inputs and expected outputs as the C# reference formatter (tests/vectors/formatter.tsv, generated by
 * running VoiceDictation.Core). Any difference is a porting bug.
 */
class FormatterVectorsTest {
    private val formatter = DictationFormatter(
        DictationOptions(
            replacements = linkedMapOf("git hub" to "GitHub", "kube" to "Kubernetes"),
            snippets = linkedMapOf("my signature" to "Thanks,\nShivam"),
        ),
    )

    @Test
    fun matches_the_reference_formatter() {
        val dir = System.getProperty("thumbfree.vectors") ?: "../../tests/vectors"
        val rows = File(dir, "formatter.tsv").readLines(Charsets.UTF_8).filter { it.isNotEmpty() && !it.startsWith("#") }
        check(rows.size > 100) { "expected the vector file, found ${rows.size} rows" }
        val failures = rows.mapNotNull { row ->
            val (continues, search, input, expected) = row.split('\t').also { require(it.size == 4) { "bad row: $row" } }
            val actual = formatter.format(unescape(input), continues == "1", search == "1")
            if (actual == unescape(expected)) null else "  [$continues$search] ${input}\n     expected: $expected\n     actual:   ${escape(actual)}"
        }
        if (failures.isNotEmpty()) fail("${failures.size} of ${rows.size} vectors differ:\n" + failures.take(25).joinToString("\n"))
    }

    private fun unescape(s: String): String {
        val sb = StringBuilder()
        var i = 0
        while (i < s.length) {
            if (s[i] == '\\' && i + 1 < s.length) {
                sb.append(when (s[i + 1]) { 'n' -> '\n'; 't' -> '\t'; 'r' -> '\r'; else -> s[i + 1] })
                i += 2
            } else {
                sb.append(s[i++])
            }
        }
        return sb.toString()
    }

    private fun escape(s: String) = s.replace("\\", "\\\\").replace("\t", "\\t").replace("\r", "\\r").replace("\n", "\\n")
}
